import java.math.BigInteger;

public final class VerifyCritical {
  private record Case(String name, int A, int E, int D,
                      String expectedN, String expectedResidue) {}

  private static final BigInteger TEN = BigInteger.TEN;
  private static final BigInteger TWO = BigInteger.TWO;
  private static final BigInteger ONE = BigInteger.ONE;

  public static void main(String[] args) {
    Case[] cases = new Case[] {
      new Case("q1_3", 740, 733, 2391,
        "",
        ""),
      new Case("q2_0", 370, 666, 2177,
        "",
        "")
    };

    int mutations = 0;
    for (Case c : cases) {
      BigInteger numerator = BigInteger.valueOf(c.A())
          .multiply(TEN.pow(c.E())).add(ONE);
      BigInteger divisor = BigInteger.valueOf(c.D());
      BigInteger[] qr = numerator.divideAndRemainder(divisor);
      require(qr[1].signum() == 0, "nonintegral quotient");
      BigInteger n = qr[0];
      BigInteger expectedN = new BigInteger(c.expectedN());
      BigInteger expectedR = new BigInteger(c.expectedResidue());
      require(n.equals(expectedN), "n mismatch");
      require(n.compareTo(TWO) > 0 && n.testBit(0), "parity/range mismatch");

      BigInteger residue = TWO.modPow(n.subtract(ONE), n);
      require(residue.equals(expectedR), "residue mismatch");
      require(!residue.equals(ONE), "Fermat test unexpectedly passed");

      require(!n.add(ONE).equals(expectedN), "n mutation accepted");
      mutations++;
      require(!residue.add(ONE).mod(n).equals(expectedR), "residue mutation accepted");
      mutations++;

      System.out.println(c.name() + " digits=" + c.E() + " fermat_failure=1");
    }
    System.out.println("JAVA_EXACT_FERMAT_PASS cases=2 mutations=" + mutations);
  }

  private static void require(boolean condition, String message) {
    if (!condition) throw new AssertionError(message);
  }
}
